package br.com.confirmacao.session.application;
import br.com.confirmacao.patient.application.PatientNotFoundException;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.professional.application.ProfessionalNotFoundException;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.scheduleblock.infrastructure.ScheduleBlockRepository;import br.com.confirmacao.session.domain.*;import br.com.confirmacao.session.infrastructure.SessionAppointmentRepository;import jakarta.persistence.EntityManager;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.*;
@Service public class SessionSeriesService{private final SessionAppointmentRepository sessions;private final PatientRepository patients;private final ProfessionalRepository professionals;private final ScheduleBlockRepository blocks;private final EntityManager entityManager;public SessionSeriesService(SessionAppointmentRepository s,PatientRepository p,ProfessionalRepository r,ScheduleBlockRepository b,EntityManager e){sessions=s;patients=p;professionals=r;blocks=b;entityManager=e;}@Transactional public List<SessionAppointment> create(UUID professionalId,UUID patientId,Instant start,Instant end,SessionModality modality,String link,String notes){if(start==null||!start.isAfter(Instant.now()))throw new IllegalArgumentException("A sessão deve ser agendada para um horário futuro");var duration=Duration.between(start,end);if(duration.isZero()||duration.isNegative())throw new IllegalArgumentException("O horário final deve ser posterior ao inicial");if(duration.compareTo(Duration.ofDays(7))>=0)throw new IllegalArgumentException("A duração da sessão deve ser inferior a sete dias");var professional=professionals.findById(professionalId).orElseThrow(()->new ProfessionalNotFoundException(professionalId));var patient=patients.findByIdAndProfessionalId(patientId,professionalId).filter(x->x.isActive()).orElseThrow(()->new PatientNotFoundException(patientId));var result=new ArrayList<SessionAppointment>();for(int week=0;week<4;week++){var seriesStart=start.plus(Duration.ofDays(week*7));var seriesEnd=seriesStart.plus(duration);if(!seriesStart.isAfter(Instant.now()))throw new IllegalArgumentException("Todas as sessões da série devem estar no futuro");if(sessions.existsByProfessionalIdAndStatusNotAndStartsAtLessThanAndEndsAtGreaterThan(professionalId,SessionStatus.CANCELED,seriesEnd,seriesStart)||blocks.existsByProfessionalIdAndStartsAtLessThanAndEndsAtGreaterThan(professionalId,seriesEnd,seriesStart))throw new SessionConflictException("Existe conflito ou bloqueio em uma das sessões da série");result.add(new SessionAppointment(professional,patient,seriesStart,seriesEnd,modality,link,notes));}sessions.saveAll(result);entityManager.createNativeQuery("UPDATE patients SET default_session_weekday=:weekday,updated_at=CURRENT_TIMESTAMP WHERE id=:id").setParameter("weekday",start.atZone(ZoneId.of(professional.getTimezone())).getDayOfWeek().getValue()).setParameter("id",patientId).executeUpdate();return result;}}
